   227|/**
   228| * The 18-step senior-developer loop. Each step maps to a state transition.
   229| * This is the canonical sequence — the worker must not skip from request to
   230| * deployment.
   231| */
   232|export const SENIOR_DEVELOPER_LOOP_STEPS: readonly { step: number; name: string; enterState: IVXTaskState }[] = [
   233|  { step: 1, name: 'Understand the requested behavior', enterState: 'ANALYZING' },
   234|  { step: 2, name: 'Retrieve relevant project context', enterState: 'ANALYZING' },
   235|  { step: 3, name: 'Inspect the actual code', enterState: 'ANALYZING' },
   236|  { step: 4, name: 'Locate related files and services', enterState: 'ANALYZING' },
   237|  { step: 5, name: 'Reproduce the problem', enterState: 'REPRODUCING' },
   238|  { step: 6, name: 'Record baseline behavior', enterState: 'REPRODUCING' },
   239|  { step: 7, name: 'Identify the root cause', enterState: 'ROOT_CAUSE_IDENTIFIED' },
   240|  { step: 8, name: 'Create an implementation plan', enterState: 'ROOT_CAUSE_IDENTIFIED' },
   241|  { step: 9, name: 'Modify the correct files', enterState: 'IMPLEMENTING' },
   242|  { step: 10, name: 'Run static checks', enterState: 'TESTING' },
   243|  { step: 11, name: 'Run unit and integration tests', enterState: 'TESTING' },
   244|  { step: 12, name: 'Run targeted regression tests', enterState: 'TESTING' },
   245|  { step: 13, name: 'Build the application', enterState: 'TESTING' },
   246|  { step: 14, name: 'Test on the required platform', enterState: 'QA_IN_PROGRESS' },
   247|  { step: 15, name: 'Commit the changes', enterState: 'READY_TO_DEPLOY' },
   248|  { step: 16, name: 'Deploy the exact commit', enterState: 'DEPLOYING' },
   249|  { step: 17, name: 'Verify production behavior', enterState: 'PRODUCTION_VERIFYING' },
   250|  { step: 18, name: 'Return evidence and remaining risks', enterState: 'VERIFIED' },
   251|] as const;
   252|
   253|/**
   254| * Map a worker stage name to a task state. This bridges the worker's
   255| * free-form stage strings to the canonical state machine.
   256| */
   257|export function stageToTaskState(stage: string | null | undefined): IVXTaskState {
   258|  const s = (stage ?? '').toUpperCase().replace(/[^A-Z_]/g, '_');
   259|  if (s.includes('RECEIVED') || s.includes('QUEUED') || s.includes('PENDING')) return 'RECEIVED';
   260|  if (s.includes('ANALYZ') || s.includes('INSPECT') || s.includes('INDEX')) return 'ANALYZING';
   261|  if (s.includes('REPRODUC') || s.includes('BASELINE')) return 'REPRODUCING';
   262|  if (s.includes('ROOT_CAUSE') || s.includes('ROOTCAUSE') || s.includes('PLAN')) return 'ROOT_CAUSE_IDENTIFIED';
   263|  if (s.includes('IMPLEMENT') || s.includes('PATCH') || s.includes('EDIT')) return 'IMPLEMENTING';
   264|  if (s.includes('CODE_CHANGED') || s.includes('CODECHANGE')) return 'CODE_CHANGED';
   265|  if (s.includes('TEST')) return 'TESTING';
   266|  if (s.includes('QA_REQUIRED') || s.includes('QAREQUIRED')) return 'QA_REQUIRED';
   267|  if (s.includes('QA_IN_PROGRESS') || s.includes('QAINPROGRESS') || s.includes('QA')) return 'QA_IN_PROGRESS';
   268|  if (s.includes('READY_TO_DEPLOY') || s.includes('READYTODEPLOY') || s.includes('READY')) return 'READY_TO_DEPLOY';
   269|  if (s.includes('DEPLOYING') || s.includes('DEPLOY_IN_PROGRESS')) return 'DEPLOYING';
   270|  if (s.includes('DEPLOYED') && !s.includes('VERIFY')) return 'DEPLOYED';
   271|  if (s.includes('PRODUCTION_VERIFY') || s.includes('VERIFYING') || s.includes('VERIFY')) return 'PRODUCTION_VERIFYING';
   272|  if (s.includes('VERIFIED') || s.includes('COMPLETE')) return 'VERIFIED';
   273|  if (s.includes('BLOCKED')) return 'BLOCKED';
   274|  if (s.includes('FAILED') || s.includes('ERROR')) return 'FAILED';
   275|  if (s.includes('NO_CHANGE') || s.includes('NOCHANGE')) return 'NO_CHANGE_REQUIRED';
   276|  return 'RECEIVED';
   277|}

