    16|describe('IVX Task State Machine', () => {
    17|  test('has exactly 17 states', () => {
    18|    expect(ALL_TASK_STATES.length).toBe(17);
    19|  });
    20|
    21|  test('RECEIVED cannot skip to DEPLOYED', () => {
    22|    expect(canTransition('RECEIVED', 'DEPLOYED')).toBe(false);
    23|  });
    24|
    25|  test('RECEIVED cannot skip to VERIFIED', () => {
    26|    expect(canTransition('RECEIVED', 'VERIFIED')).toBe(false);
    27|  });
    28|
    29|  test('RECEIVED -> ANALYZING is legal', () => {
    30|    expect(canTransition('RECEIVED', 'ANALYZING')).toBe(true);
    31|  });
    32|
    33|  test('CODE_CHANGED requires filesChangedCount > 0', () => {
    34|    const r = assertCanTransition({
    35|      from: 'IMPLEMENTING', to: 'CODE_CHANGED',
    36|      isDevelopmentTask: true, filesChangedCount: 0,
